pub fn draw_rmk_logo<D: embedded_graphics::draw_target::DrawTarget<Color = embedded_graphics::pixelcolor::BinaryColor>>(
    display: &mut D,
) {
    let cols = 128;
    let pages = 4;
    for page in 0..pages {
        for col in 0..cols {
            let byte = RMK_LOGO[page * cols + col];
            if byte == 0 {
                continue;
            }
            for bit in 0..8u32 {
                if byte & (1 << bit) != 0 {
                    let x = col as i32;
                    let y = page as i32 * 8 + bit as i32;
                    embedded_graphics::Pixel(
                        embedded_graphics::geometry::Point::new(x, y),
                        embedded_graphics::pixelcolor::BinaryColor::On,
                    )
                    .draw(display)
                    .ok();
                }
            }
        }
    }
}

